import { SetMetadata } from '@nestjs/common';
import { ON_WORKER_EVENT_METADATA } from '../bull.constants.js';
/**
 * Registers a worker event listener.
 * Class that contains worker event listeners must be annotated
 * with the "Processor" decorator.
 *
 * @publicApi
 */
export const OnWorkerEvent = (eventName) => SetMetadata(ON_WORKER_EVENT_METADATA, {
    eventName: eventName,
});
